INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (1, 1, 1, 'Apple iPhone 15 Pro Max (256GB, Natural Titanium)', 'Apple Inc.', 134900, 159900, 'iPhone 15 Pro Max forged in aerospace-grade natural titanium with the groundbreaking A17 Pro chip, customizable Action button, 48MP main camera with 5x optical telephoto lens, and USB-C with USB 3 speeds.', 'mi-redmi-note-4-na-original-imaeqdxgtcgbgvfh.jpeg', 'mi-redmi-note-4-na-original-imaeqdxhgnerzpeg.jpeg', 'mi-redmi-note-4-na-original-imaeqdxqcrfshtqu.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (2, 1, 1, 'Samsung Galaxy S24 Ultra (512GB, Titanium Gray, Galaxy AI)', 'Samsung', 129999, 144999, 'Meet Galaxy S24 Ultra with Galaxy AI. Search like never before with Circle to Search, get real-time voice translation on calls, snap vivid 200MP photos with ProVisual engine, powered by Snapdragon 8 Gen 3.', 'apple-iphone-6-1.jpeg', 'apple-iphone-6-2.jpeg', 'apple-iphone-6-3.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (3, 1, 2, 'Apple MacBook Pro 16" (M3 Max Chip, 36GB RAM, 1TB SSD)', 'Apple Inc.', 299900, 349900, 'The most advanced Mac laptop ever. Powered by the M3 Max chip with a 16-core CPU and 40-core GPU, Liquid Retina XDR display with 1600 nits peak brightness, and up to 22 hours of all-day battery life.', 'mi-redmi-note-4-1.jpeg', 'mi-redmi-note-4-2.jpeg', 'mi-redmi-note-4-3.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (4, 1, 2, 'Dell XPS 15 OLED InfinityEdge (Intel Core i9 14th Gen, RTX 4070)', 'Dell', 219900, 249900, 'Crafted from CNC machined aluminum and carbon fiber, featuring a 3.5K OLED touchscreen display, NVIDIA GeForce RTX 4070 8GB GPU, and quad-speaker sound system with Waves Nx 3D audio.', 'lenovo-k6-power-k33a42-1.jpeg', 'lenovo-k6-power-k33a42-2.jpeg', 'lenovo-k6-power-k33a42-3.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (5, 1, 3, 'Sony WH-1000XM5 Wireless Noise-Cancelling Headphones', 'Sony', 29990, 34990, 'Industry-leading noise canceling with two processors and 8 microphones. Magnificent sound quality with 30mm driver unit, crystal clear hands-free calling with 4 beamforming mics, and 30-hour battery life with quick charge.', 'lenovo-k5-note-pa330010in-1.jpeg', 'lenovo-k5-note-pa330116in-2.jpeg', 'lenovo-k5-note-pa330116in-3.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (6, 1, 3, 'Bose QuietComfort Ultra Spatial Audio Earbuds', 'Bose', 24900, 29900, 'Groundbreaking spatial audio for more immersive listening. World-class noise cancellation tuned specifically to the shape of your ears with CustomTune technology, and seamless touch controls.', 'micromax-canvas-mega-4g-1.jpeg', 'micromax-canvas-mega-4g-2.jpeg', 'micromax-canvas-mega-4g-3.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (7, 1, 4, 'Apple Watch Ultra 2 (49mm Titanium Case, GPS + Cellular)', 'Apple Inc.', 84900, 89900, 'The ultimate sports and adventure watch. Features the S9 SiP with Double Tap gesture, a 3000-nit Always-On Retina display, precision dual-frequency GPS, and up to 72 hours in Low Power Mode.', 'samsung-galaxy-on5-sm-2.jpeg', 'samsung-galaxy-on5-sm-3.jpeg', 'samsung-galaxy-on7-sm-1.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (8, 1, 5, 'LG C3 65" 4K OLED evo Smart TV (120Hz, Dolby Vision Atmos)', 'LG Electronics', 169990, 229990, 'Self-lit OLED pixels create infinite contrast and 100% color fidelity. Powered by the α9 AI Processor Gen6, 0.1ms response time, NVIDIA G-Sync, AMD FreeSync Premium, and Dolby Atmos audio.', 'oppo-a57-na-original-1.jpeg', 'oppo-a57-na-original-2.jpeg', 'oppo-a57-na-original-3.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (9, 1, 6, 'GoPro HERO12 Black (5.3K60 Ultra HD Action Camera, HDR Video)', 'GoPro', 37990, 44990, 'Incredible image quality with 5.3K video and HDR. HyperSmooth 6.0 stabilization with 360 Horizon Lock, rugged and waterproof to 33ft (10m), and double the runtime with Enduro battery.', 'amzer-amz98947-original-1.jpeg', 'amzer-amz98947-original-2.jpeg', 'amzer-amz98947-original-3.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (10, 5, 16, 'Sony PlayStation 5 Slim 1TB Console (4K 120Hz HDR, DualSense)', 'Sony Interactive', 49990, 54990, 'Experience lightning-fast loading with an ultra-high speed 1TB SSD, deeper immersion with haptic feedback, adaptive triggers, and 3D Audio, and an all-new slim design with attachable Ultra HD Blu-ray disc drive.', '6e0ef9575326db6a182ab34f87dadaec.jpg', '6e0ef9575326db6a182ab34f87dadaec.jpg', '6e0ef9575326db6a182ab34f87dadaec.jpg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (11, 5, 16, 'Nintendo Switch OLED Model (64GB Storage, Vibrant 7" Screen)', 'Nintendo', 29990, 34990, 'Play at home on the TV or on-the-go with a vibrant 7-inch OLED screen. Features a wide adjustable stand, a dock with a wired LAN port, 64 GB of internal storage, and enhanced audio in handheld and tabletop modes.', 'acer-aspire-notebook-original-1.jpeg', 'acer-aspire-notebook-original-2.jpeg', 'acer-aspire-notebook-original-3.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (12, 5, 17, 'Logitech G PRO X Superlight 2 Wireless Gaming Mouse (32K DPI)', 'Logitech G', 13990, 16990, 'Next generation of our championship-winning 60g pro gaming mouse. Equipped with LIGHTFORCE hybrid switches, HERO 2 sensor with over 32,000 DPI, and 95 hours of battery life with USB-C charging.', 'micromax-lt777w-2-in-1-laptop-original-1.jpeg', 'micromax-lt777w-2-in-1-laptop-original-2.jpeg', 'micromax-lt777w-2-in-1-laptop-original-3.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (13, 5, 17, 'Keychron Q1 Pro Custom Wireless Mechanical Keyboard (Hot-Swap)', 'Keychron', 17990, 21990, 'Full aluminum 75% mechanical keyboard with wireless Bluetooth 5.1 and wired connectivity, QMK/VIA programmable keys, double-gasket design for acoustic dampening, and south-facing RGB backlighting.', 'hp-notebook-original-1.jpeg', 'hp-notebook-original-2.jpeg', 'hp-notebook-original-3.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (14, 2, 7, 'Nike Air Jordan 1 Retro High OG (Chicago Lost & Found)', 'Nike', 16995, 19995, 'The iconic 1985 silhouette returns with premium cracked leather accents, classic high-top ankle padding, encapsulated Nike Air-Sole cushioning in the heel, and the legendary Varsity Red/Black/Sail colorway.', 'lenovo-ideapad-notebook-3.jpeg', 'lenovo-ideapad-notebook-original-1.jpeg', 'lenovo-ideapad-notebook-original-2.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (15, 2, 7, 'Adidas Ultraboost Light Running Shoes (Primeknit, Continental)', 'Adidas', 14999, 18999, 'Experience epic energy return with our lightest Ultraboost ever. 30% lighter BOOST material with Linear Energy Push system and Continental Better Rubber outsole for superior grip in wet and dry conditions.', 'diary-of-a-wimpy-kid-do-it-yourself-book-original-1.jpeg', 'diary-of-a-wimpy-kid-do-it-yourself-book-original-1.jpeg', 'diary-of-a-wimpy-kid-do-it-yourself-book-original-1.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (16, 3, 10, 'Herman Miller Aeron Ergonomic Chair (Fully Loaded, Graphite)', 'Herman Miller', 119000, 145000, 'The benchmark for ergonomic seating. Pellicle 8Z breathable elastomeric suspension, PostureFit SL adjustable sacral and lumbar back support, fully adjustable armrests, and Harmonic 2 tilt mechanism.', '22-thea-stilton-and-the-tropical-treasure-original-1.jpeg', '22-thea-stilton-and-the-tropical-treasure-original-1.jpeg', '22-thea-stilton-and-the-tropical-treasure-original-1.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (17, 3, 11, 'Dyson V15 Detect Cordless Vacuum Cleaner (Laser Dust Detection)', 'Dyson', 59900, 69900, 'Dyson''s most powerful, intelligent cordless vacuum. A precisely-angled laser illuminates invisible microscopic dust on hard floors, with an acoustic piezo sensor that counts and measures particle sizes.', 'inaf245-queen-rosewood-sheesham-induscraft-na-honey-brown-original-1.jpeg', 'inaf245-queen-rosewood-sheesham-induscraft-na-honey-brown-original-2.jpeg', 'inaf245-queen-rosewood-sheesham-induscraft-na-honey-brown-original-3.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (18, 3, 12, 'Nordic Solid Oak Minimalist King Bed with Headboard Storage', 'Nordic Craft', 42990, 54990, 'Crafted from 100% natural European solid oak with a matte organic oil finish. Sturdy slatted base, silent joint construction, and integrated warm ambient LED headboard lighting.', 'flbdorsabrqbblk-queen-carbon-steel-home-by-nilkamal-na-na-original-1.jpeg', 'flbdorsabrqbblk-queen-carbon-steel-home-by-nilkamal-na-na-original-2.jpeg', 'flbdorsabrqbblk-queen-carbon-steel-home-by-nilkamal-na-na-original-3.jpeg', 0, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (19, 4, 14, 'Atomic Habits: An Easy & Proven Way to Build Good Habits (Hardcover)', 'Penguin Random House', 499, 799, 'The definitive guide to breaking bad behaviors and adopting good ones in four steps. Written by habit expert James Clear, this #1 New York Times bestseller has sold over 15 million copies worldwide.', '1.jpeg', '2.jpeg', '3.jpeg', 50, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (20, 4, 13, 'The Psychology of Money: Timeless Lessons on Wealth and Greed', 'Harriman House', 399, 599, 'Doing well with money isn''t necessarily about what you know. It''s about how you behave. Morgan Housel shares 19 short stories exploring the strange ways people think about money and risk.', '1.jpeg', '2.jpeg', '3.jpeg', 50, 'In Stock');
INSERT INTO products (id, category, subCategory, productName, productCompany, productPrice, productPriceBeforeDiscount, productDescription, productImage1, productImage2, productImage3, shippingCharge, productAvailability) VALUES (21, 4, 15, 'Deep Work: Rules for Focused Success in a Distracted World', 'Grand Central Publishing', 450, 650, 'Deep work is the ability to focus without distraction on a cognitively demanding task. Wall Street Journal bestselling author Cal Newport explains how to master this superpower in an interconnected economy.', '51qTiWJdL2L._SL1500_.jpg', '61HXVQ+KUQL._SL1500_.jpg', '71QuCUBXcNL._SL1500_.jpg', 50, 'In Stock');
